import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

async function totalFor(items, prices) {
  const pricing = { priceOf: async (sku) => prices[sku] }
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const base = `http://localhost:${server.address().port}`
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    const order = await res.json()
    const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
    assert.equal(fetched.total, order.total)
    return order.total
  } finally {
    server.close()
  }
}

// Characterization tests: they pin CURRENT behaviour, including questionable parts.
const cases = [
  ['single item, no discount', [{ sku: 'a', qty: 1 }], { a: 10 }, 10],
  ['sums price * qty across items', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 3 }], { a: 10, b: 5 }, 35],
  ['exactly 100 gets no discount', [{ sku: 'a', qty: 10 }], { a: 10 }, 100],
  ['just over 100 gets 10% off (floored)', [{ sku: 'a', qty: 1 }], { a: 100.5 }, 90],
  ['large order 10% off', [{ sku: 'a', qty: 20 }], { a: 10 }, 180],
  ['very large order: still a flat 10%, no extra tier', [{ sku: 'a', qty: 1000 }], { a: 10 }, 9000],
  ['fractional prices truncate cents, not round (EUR 19.99 -> 19)', [{ sku: 'a', qty: 1 }], { a: 19.99 }, 19],
  ['discounted total truncates cents (101 * 0.9 = 90.9 -> 90)', [{ sku: 'a', qty: 1 }], { a: 101 }, 90],
]
for (const [name, items, prices, expected] of cases) {
  test(name, async () => assert.equal(await totalFor(items, prices), expected))
}

test('empty items rejected', async () => {
  const server = createServer(createApp({ pricing: { priceOf: async () => 1 } }))
  await new Promise((r) => server.listen(0, r))
  const res = await fetch(`http://localhost:${server.address().port}/orders`, { method: 'POST', body: '{"items":[]}' })
  server.close()
  assert.equal(res.status, 400)
})
EOF
